<?php require_once __DIR__.'/includes/bootstrap.php';$pageTitle='Services & Programs';$q=trim($_GET['q']??'');$category=trim($_GET['category']??'');$services=rows($pdo,'SELECT * FROM services WHERE (:c="" OR category=:c) AND (:q="" OR title LIKE :like) ORDER BY category,title',['c'=>$category,'q'=>$q,'like'=>'%'.$q.'%']);$events=rows($pdo,'SELECT * FROM events WHERE event_date>=CURDATE() ORDER BY event_date');$categories=array_unique(array_filter(array_column(rows($pdo,'SELECT category FROM services ORDER BY category'),'category')));require __DIR__.'/includes/header.php';?><main><a class="back" href="dashboard.php"><i class="fa-solid fa-arrow-left"></i> Explore information / Services & Programs</a><section class="hero"><i class="fa-solid fa-hand-holding-heart"></i><div><h1>Services & Programs</h1><p>Find schedules, contact information, and the latest updates.</p></div></section><section class="section"><article class="panel"><form class="form-grid" method="get"><div><label for="q">Search services</label><input id="q" name="q" value="<?= h($q) ?>" placeholder="Health, livelihood..."></div><div><label for="category">Category</label><select id="category" name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option <?= $category===$c?'selected':'' ?>><?= h($c) ?></option><?php endforeach;?></select></div><div class="full"><button class="button">Search services</button></div></form></article></section><section class="section"><h2>Services</h2><div class="grid" style="margin-top:18px"><?php if(!$services):?><div class="panel empty">No services have been published yet.</div><?php else:foreach($services as $s):?><article class="panel"><span class="meta"><?= h($s['category']??'Program') ?></span><h3><?= h($s['title']??'Service') ?></h3><p><?= h($s['description']??'') ?></p><span class="meta"><i class="fa-regular fa-clock"></i> <?= h($s['schedule']??'Schedule to be announced') ?><br>Contact: <?= h($s['contact']??'Barangay office') ?></span></article><?php endforeach;endif;?></div></section><section class="section"><h2>Upcoming events</h2><div class="grid" style="margin-top:18px"><?php if(!$events):?><div class="panel empty">No upcoming events have been published yet.</div><?php else:foreach($events as $e):?><article class="panel"><span class="meta"><?= h(date('F j, Y',strtotime($e['event_date']))) ?> · <?= h($e['location']??'') ?></span><h3><?= h($e['title']) ?></h3><p><?= h($e['description']??'') ?></p><?php if(logged_in()):?><form method="post" action="rsvp.php"><input type="hidden" name="csrf_token" value="<?= csrf() ?>"><input type="hidden" name="event_id" value="<?= (int)$e['id'] ?>"><label>Number of attendees</label><input type="number" name="party_size" min="1" max="<?= (int)($e['capacity']??99) ?>" value="1"><button class="button" style="margin-top:10px">RSVP</button></form><?php else:?><button class="button" data-requires-login data-authenticated="0" data-intent="RSVP for this event">RSVP</button><?php endif;?></article><?php endforeach;endif;?></div></section><section class="section"><article class="panel"><h2>Subscribe to alerts</h2><?php if(isset($_GET['subscribed'])):?><div class="success">You are subscribed to alerts.</div><?php elseif(logged_in()):?><form method="post" action="subscribe.php" class="form-grid"><input type="hidden" name="csrf_token" value="<?= csrf() ?>"><input type="hidden" name="return" value="services-programs.php"><div><label>Email address</label><input name="email" type="email" required></div><div style="align-self:end"><button class="button">Subscribe</button></div></form><?php else:?><p>Sign in to receive new service and event updates.</p><button class="button" data-requires-login data-authenticated="0" data-intent="subscribe to alerts">Subscribe to alerts</button><?php endif;?></article></section></main><?php require __DIR__.'/includes/login-gate-modal.php';require __DIR__.'/includes/footer.php';?>
